-- Flora/fauna content correction. Owner runs in Supabase SQL editor.
-- Backups preserve all original records and ratings. No policy statements.
-- Old website cultures are archived; fresh real Gemini cultures receive new ids.
begin;
create table if not exists public.punnett_content_backups (content_key text primary key, row_data jsonb not null, saved_at timestamptz not null default now());
alter table public.punnett_content_backups enable row level security;
revoke all on public.punnett_content_backups from public, anon, authenticated;
insert into public.punnett_content_backups(content_key,row_data) select 'lab:'||id::text,to_jsonb(s) from public.lab_specimens s on conflict do nothing;
insert into public.punnett_content_backups(content_key,row_data) select 'bench:'||id::text,to_jsonb(s) from public.punnett_bench_specimens s on conflict do nothing;
update public.lab_specimens set label=E'Gympie-gympie (Dendrocnide moroides)',notes=E'This Australian stinging plant carries fine hairs that deliver potent toxins and can cause lasting pain. Soft-looking leaves; aggressively enforced personal space.' where id=1 and code=E'LAB-001';
update public.punnett_bench_specimens set label=E'Gympie-gympie (Dendrocnide moroides)',notes=E'This Australian stinging plant carries fine hairs that deliver potent toxins and can cause lasting pain. Soft-looking leaves; aggressively enforced personal space.',revision=revision+1,updated_at=now() where label in (E'Gympie-gympie Leaf (Dendrocnide moroides)',E'Gympie-gympie (Dendrocnide moroides)');
update public.lab_specimens set label=E'Cane toad (Rhinella marina)',notes=E'This large toad was introduced to Australia in 1935 to control cane beetles. The effort failed, and the toads spread. Pest-control hire; permanent tenant.' where id=2 and code=E'LAB-002';
update public.punnett_bench_specimens set label=E'Cane toad (Rhinella marina)',notes=E'This large toad was introduced to Australia in 1935 to control cane beetles. The effort failed, and the toads spread. Pest-control hire; permanent tenant.',revision=revision+1,updated_at=now() where label in (E'Cane Toad (Rhinella marina), Roadkill Flattened',E'Cane toad (Rhinella marina)');
update public.lab_specimens set label=E'Exploding ant (Colobopsis explodens)',notes=E'Small workers defend the colony by rupturing their bodies and releasing sticky gland secretions, killing themselves. A security system with no reset button.' where id=3 and code=E'LAB-003';
update public.punnett_bench_specimens set label=E'Exploding ant (Colobopsis explodens)',notes=E'Small workers defend the colony by rupturing their bodies and releasing sticky gland secretions, killing themselves. A security system with no reset button.',revision=revision+1,updated_at=now() where label in (E'Exploding Ant (Colobopsis explodens)',E'Exploding ant (Colobopsis explodens)');
update public.lab_specimens set label=E'Pacific razor clam (Siliqua patula)',notes=E'This Pacific bivalve burrows vertically through sand and can dig roughly a foot per minute. The beach''s least sociable elevator.' where id=4 and code=E'LAB-004';
update public.punnett_bench_specimens set label=E'Pacific razor clam (Siliqua patula)',notes=E'This Pacific bivalve burrows vertically through sand and can dig roughly a foot per minute. The beach''s least sociable elevator.',revision=revision+1,updated_at=now() where label in (E'Severed Clam Foot (Siliqua patula)',E'Pacific razor clam (Siliqua patula)');
update public.lab_specimens set label=E'Zombie-ant fungus (Ophiocordyceps unilateralis complex)',notes=E'These fungi manipulate carpenter ants into gripping vegetation before a spore-bearing stalk grows from the dead ant''s head. The final performance review has a fungal attachment.' where id=5 and code=E'LAB-005';
update public.punnett_bench_specimens set label=E'Zombie-ant fungus (Ophiocordyceps unilateralis complex)',notes=E'These fungi manipulate carpenter ants into gripping vegetation before a spore-bearing stalk grows from the dead ant''s head. The final performance review has a fungal attachment.',revision=revision+1,updated_at=now() where label in (E'Zombie-Ant Fungus (Ophiocordyceps unilateralis)',E'Zombie-ant fungus (Ophiocordyceps unilateralis complex)');
update public.lab_specimens set label=E'Dead man''s fingers (Xylaria polymorpha)',notes=E'This fungus produces dark, finger-shaped reproductive structures on dead or dying wood. A rotting log now appears to be raising a corpse''s hand. The forest has chosen deeply unsettling customer service.' where id=6 and code=E'LAB-006';
update public.punnett_bench_specimens set label=E'Dead man''s fingers (Xylaria polymorpha)',notes=E'This fungus produces dark, finger-shaped reproductive structures on dead or dying wood. A rotting log now appears to be raising a corpse''s hand. The forest has chosen deeply unsettling customer service.',revision=revision+1,updated_at=now() where label in (E'Dead Man''s Fingers (Xylaria polymorpha)',E'Dead man''s fingers (Xylaria polymorpha)');
update public.lab_specimens set label=E'Sea cucumbers (Holothuroidea)',notes=E'Some sea cucumbers expel internal organs when threatened and can regenerate the lost parts. Predator arrives; this animal rage-quits its own anatomy. Nature''s most aggressive unboxing video.' where id=7 and code=E'LAB-007';
update public.punnett_bench_specimens set label=E'Sea cucumbers (Holothuroidea)',notes=E'Some sea cucumbers expel internal organs when threatened and can regenerate the lost parts. Predator arrives; this animal rage-quits its own anatomy. Nature''s most aggressive unboxing video.',revision=revision+1,updated_at=now() where label in (E'Sea Cucumber Evisceration Cluster (Holothuroidea)',E'Sea cucumbers (Holothuroidea)');
update public.lab_specimens set label=E'Tongue-replacing isopod (Cymothoa exigua)',notes=E'This parasitic crustacean can cause a fish''s tongue to degenerate and attach where it once sat. A roommate who takes the phrase ''shared kitchen'' too literally.' where id=8 and code=E'LAB-008';
update public.punnett_bench_specimens set label=E'Tongue-replacing isopod (Cymothoa exigua)',notes=E'This parasitic crustacean can cause a fish''s tongue to degenerate and attach where it once sat. A roommate who takes the phrase ''shared kitchen'' too literally.',revision=revision+1,updated_at=now() where label in (E'Tongue-Eating Isopod (Cymothoa exigua)',E'Tongue-replacing isopod (Cymothoa exigua)');
update public.lab_specimens set label=E'Northern fulmar (Fulmarus glacialis)',notes=E'Northern fulmars defend nesting sites by spitting foul-smelling stomach oil at intruders. Personal space, enforced with salad dressing.' where id=9 and code=E'LAB-009';
update public.punnett_bench_specimens set label=E'Northern fulmar (Fulmarus glacialis)',notes=E'Northern fulmars defend nesting sites by spitting foul-smelling stomach oil at intruders. Personal space, enforced with salad dressing.',revision=revision+1,updated_at=now() where label in (E'Fulmar Chick Vomit Extract (Fulmarus glacialis)',E'Northern fulmar (Fulmarus glacialis)');
update public.lab_specimens set label=E'Hairy frog (Astylosternus robustus)',notes=E'This frog can deploy sharp toe-bone claws through its skin when threatened. The emergency toolkit has no regard for the packaging.' where id=10 and code=E'LAB-010';
update public.punnett_bench_specimens set label=E'Hairy frog (Astylosternus robustus)',notes=E'This frog can deploy sharp toe-bone claws through its skin when threatened. The emergency toolkit has no regard for the packaging.',revision=revision+1,updated_at=now() where label in (E'Hairy Frog (Trichobatrachus robustus)',E'Hairy frog (Astylosternus robustus)');
update public.lab_specimens set label=E'Surinam toad (Pipa pipa)',notes=E'Females carry developing young in pockets of skin on their backs; the offspring emerge as tiny, fully formed frogs. A family apartment building with extremely personal plumbing.' where id=11 and code=E'LAB-011';
update public.punnett_bench_specimens set label=E'Surinam toad (Pipa pipa)',notes=E'Females carry developing young in pockets of skin on their backs; the offspring emerge as tiny, fully formed frogs. A family apartment building with extremely personal plumbing.',revision=revision+1,updated_at=now() where label in (E'Surinam Toad Dorsal Skin (Pipa pipa)',E'Surinam toad (Pipa pipa)');
